"use strict";(self.webpackChunkdocs_next=self.webpackChunkdocs_next||[]).push([[92096],{22837:e=>{e.exports=JSON.parse('{"tag":{"label":"searchxng","permalink":"/docs-next/pr-preview/pr-401/docs/tags/searchxng","allTagsPath":"/docs-next/pr-preview/pr-401/docs/tags","count":1,"items":[{"id":"blueprints/by-use-case/ai/litellm/deploy-openwebui-on-cce","title":"Deploy Open WebUI on CCE","description":"Open WebUI is a self-hosted web interface for interacting with large language models. It provides a chat-based UI that connects to OpenAI-compatible APIs, making it easy to test and use different models without building custom frontends. In this blueprint, Open WebUI acts as the user-facing layer on top of the LLM gateway. It allows users and teams to interact with the models exposed through LiteLLM, without needing to know where those models are running. This makes it a practical tool for internal adoption, enabling non-developers and developers alike to access LLM capabilities through a browser.","permalink":"/docs-next/pr-preview/pr-401/docs/blueprints/by-use-case/ai/litellm/deploy-openwebui-on-cce"}],"unlisted":false}}')}}]);